def backfill_seen(apps, schema_editor):
    """Work given before ring-until-seen: count it as seen when the person already said "Got it" to it (or answered
    JARVIS about it), or has started, held or finished it. Otherwise every old task would read "Not seen yet"."""
    SharedTask = apps.get_model("core", "SharedTask")
    Alert = apps.get_model("core", "Alert")
    for task in SharedTask.objects.filter(assignee_type="USER", seen_at__isnull=True).exclude(origin="SELF").iterator():
        acked = (Alert.objects.filter(ref_type="shared_task", ref_id=str(task.id), kind="TASK_ASSIGNED",
                                      recipient_id=task.assignee_user_id, acknowledged_at__isnull=False)
                 .order_by("acknowledged_at").values_list("acknowledged_at", flat=True).first())
        seen = acked or (task.updated_at if task.status != "OPEN" else None)
        if seen:
            SharedTask.objects.filter(id=task.id).update(seen_at=seen)


